<?= view('layout/header',['title'=>'Sales History']) ?><div class="top"><h1>Sales History</h1><a class="btn" href="<?= site_url('sales/new') ?>">Record sale</a></div><table><tr><th>Date</th><th>Product</th><th>Customer</th><th>Staff</th><th>Qty</th><th>Total</th></tr><?php foreach($sales as $s): ?><tr><td><?= esc($s['created_at']) ?></td><td><?= esc($s['product_name']) ?></td><td><?= esc($s['customer_name']??'Walk-in') ?></td><td><?= esc($s['staff_name']) ?></td><td><?= esc($s['quantity']) ?></td><td><?= number_format($s['total_price'],2) ?></td></tr><?php endforeach ?></table><?= view('layout/footer') ?>
